class PrefetchLimitTests(TestDataMixin, TestCase):
    def test_m2m_forward(self):
        authors = Author.objects.prefetch_related(
            Prefetch("books", Book.objects.all()[1:2], to_attr="limited")
        )
        with self.assertNumQueries(2):
            result = {a.name: [b.title for b in a.limited] for a in authors}
        full = {a.name: [b.title for b in a.books.all()[1:2]] for a in Author.objects.all()}
        self.assertEqual(result, full)

    def test_m2m_reverse(self):
        books = Book.objects.prefetch_related(
            Prefetch("authors", Author.objects.all()[:1], to_attr="limited")
        )
        with self.assertNumQueries(2):
            result = {b.title: [a.name for a in b.limited] for b in books}
        full = {b.title: [a.name for a in b.authors.all()[:1]] for b in Book.objects.all()}
        self.assertEqual(result, full)

    def test_reverse_fk(self):
        for house in House.objects.all():
            Room.objects.create(name="a", house=house)
            Room.objects.create(name="b", house=house)
            Room.objects.create(name="c", house=house)
        houses = House.objects.prefetch_related(
            Prefetch("rooms", Room.objects.order_by("-name")[:2], to_attr="limited")
        )
        with self.assertNumQueries(2):
            result = [[r.name for r in h.limited] for h in houses]
        self.assertTrue(result)
        self.assertTrue(all(names == ["c", "b"] for names in result))

    def test_generic_relation(self):
        for book in (self.book1, self.book2):
            for tag in ("a", "b", "c"):
                TaggedItem.objects.create(tag=tag, content_object=book)
        books = Book.objects.filter(pk__in=[self.book1.pk, self.book2.pk])
        books = books.prefetch_related(
            Prefetch("tags", TaggedItem.objects.order_by("tag")[1:3], to_attr="limited")
        )
        with self.assertNumQueries(3):
            result = [[t.tag for t in b.limited] for b in books]
        self.assertEqual(result, [["b", "c"], ["b", "c"]])


